import math

def make_square(n):
	a = n ** 0.5 // 2
	j = int(n ** 0.5)
	while a <= j:
		temp = n - a * a
		k = temp ** 0.5
		if math.ceil(k) == int(k):
			return (int(k), int(a))
		a += 1
	return (-1,)

def solve(n):
	MAX = 2 * 10 ** 5
	mul = 1
	while n > MAX:
		n /= 4
		mul *= 2
	res = make_square(n)
	if res == (-1,):
		print(-1)
	else:
		print(res[0] * mul, res[1] * mul)

def printf(a):
	if a:
		print('YES')
	else:
		print('NO')
for _ in range(int(input())):
	n = int(input())
	solve(n)
